// Validates the request the OneJarc server forwards (POST, JSON body, X-OneJarc-* headers).
// Output: { ok: true, id, ... } or { ok: false, status, body } (answered by "Respond").
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : null;
const fail = (status, message) => [{ json: { ok: false, status, body: { success: false, error: message } } }];
const isObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);

// The OneJarc server only forwards admin actions for admins and always sends this header.
// (Real protection for the URL itself: add Header Auth to the Webhook node later.)
if (String(headers['x-onejarc-user-is-admin'] || '').toLowerCase() !== 'true') return fail(403, 'Admin access is required.');
if (!body) return fail(400, 'The request body must be a JSON object.');
const id = typeof body.id === 'string' ? body.id.trim() : '';
if (!id || id.length > 200 || /[\u0000-\u001f]/.test(id)) return fail(400, 'A tool id is required.');

// Matches the document whether its _id is an ObjectId or a string, or whether it uses a
// separate string "id" field (get-tools.js accepts either). $literal stops an id that starts
// with "$" from being read as a field path.
const match = { $or: [{ $expr: { $eq: [{ $toString: '$_id' }, { $literal: id }] } }, { id }] };
const entry = body.entry;
if (!isObject(entry) || !isObject(entry.draft)) return fail(400, 'entry.draft must be an object.');
if (typeof entry.draft.name !== 'string' || !entry.draft.name.trim()) return fail(400, 'entry.draft.name is required.');
if (entry.published !== undefined && entry.published !== null && !isObject(entry.published)) return fail(400, 'entry.published must be an object or null.');
// For duplicate, id is the SOURCE tool and entry is the new copy.
return [{ json: { ok: true, id, draft: entry.draft } }];

// ToolDefinition (frontend) -> stored MongoDB fields. Inverse of toCatalogEntry() in
// site/assets/get-tools.js; same top-level fields create-tool writes (toolPayload()).
function toStored(d) {
  const str = (v) => (typeof v === 'string' ? v : v === undefined || v === null ? '' : String(v));
  const isPowerBI = d.category === 'Power BI';
  return {
    toolName: str(d.name).trim(),
    category: str(d.category),
    description: str(d.description),
    link: str(d.applicationUrl),
    owner: str(d.owner),
    tab: ['same-tab', 'embedded'].includes(d.openBehavior) ? d.openBehavior : 'new-tab',
    iconImage: str(d.iconImage),
    iconKey: str(d.iconKey),
    color: str(d.color),
    status: str(d.status),
    // Only Power BI tools carry these; cleared otherwise so a category change leaves no stale values.
    workspaceId: isPowerBI ? str(d.workspaceId).trim() : '',
    allowedRoles: isPowerBI && Array.isArray(d.allowedRoles) ? [...new Set(d.allowedRoles.map(String))] : [],
    // Full definition; get-tools.js merges record.draft over the top-level fields.
    draft: d,
  };
}
const input = $input.first().json;
const now = new Date().toISOString(); // stored as an ISO string: get-tools.js reads createdAt/updatedAt as strings
return [{ json: { ...toStored(input.draft), published: null, enabled: true, archived: false, createdAt: now, updatedAt: now } }];

// Normalises the insert result; the new document's id is returned as "id".
const input = $('Validate input').first().json;
const r = $input.first().json || {};
if (r.error || (r.json && r.json.error) || r.id === undefined || r.id === null) return [{ json: { status: 500, body: { success: false, error: 'The database insert failed. Check the n8n execution log.' } } }];
return [{ json: { status: 200, body: { success: true, id: String(r.id), sourceId: input.id } } }];

// Error output of a MongoDB node (connection, credential, query or write failure).
// Details stay in the n8n execution log; the admin sees a short JSON error.
return [{ json: { status: 500, body: { success: false, error: 'The database operation failed. Check the n8n execution log.' } } }];
